#!/usr/bin/env python3
"""Keep agents away from generated files.

factory/main.py and factory/llm.py are generated from the agent OpenAPI spec by
scripts/gen_llm.py. Hand edits get overwritten on the next generation, and reading
them wastes context, so any tool call that touches them is blocked.
"""
import json
import sys

PROTECTED = ("factory/main.py", "factory/llm.py")

event = json.load(sys.stdin)
tool_input = json.dumps(event.get("tool_input", {}))

for path in PROTECTED:
    if path in tool_input or path.split("/")[-1] in tool_input:
        print(
            f"{path} is generated by scripts/gen_llm.py. Do not read or modify it; "
            "change the generator instead.",
            file=sys.stderr,
        )
        sys.exit(2)
